BEGIN;
SET search_path=public,extensions;
SELECT no_plan();
SELECT has_function('public','set_property_tour',ARRAY['uuid','text'],'owner tour RPC exists');
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES('88888888-0000-4000-8000-000000000001','tour-owner@example.test',now()),('88888888-0000-4000-8000-000000000002','tour-other@example.test',now()),('88888888-0000-4000-8000-000000000003','tour-unverified@example.test',NULL);
SELECT set_config('request.jwt.claims','{"sub":"88888888-0000-4000-8000-000000000001"}',true);
CREATE TEMP TABLE f AS SELECT public.create_property('Tour apartment','Description','Cotroceni','Tour private address','apartment',50,2,1,2019,10000000,50000,'{}') j;
CREATE TEMP TABLE l AS SELECT id FROM app.listings WHERE property_id=(SELECT (j->>'id')::uuid FROM f) AND transaction_type='sale';
SELECT is(public.set_property_tour((SELECT (j->>'id')::uuid FROM f),'https://www.kuula.co/share/collection/7ABcd?logo=1&info=0')->>'tour_url','https://kuula.co/share/collection/7ABcd?logo=1&info=0','owner saves canonical Kuula URL');
SELECT is(public.get_listing((SELECT id FROM l))->>'tour_url','https://kuula.co/share/collection/7ABcd?logo=1&info=0','public listing includes tour URL');
SELECT ok(NOT public.get_listing((SELECT id FROM l)) ? 'exact_address','tour listing excludes exact address');
SELECT ok(NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.get_catalogue()) item WHERE item->>'property_id'=(SELECT j->>'id' FROM f) AND item->>'tour_url'<>'https://kuula.co/share/collection/7ABcd?logo=1&info=0'),'both public transaction listings share tour');
SELECT is(public.set_property_tour((SELECT (j->>'id')::uuid FROM f),'https://my.matterport.com/show/?m=AbC123xyz&play=1&qs=1')->>'tour_url','https://my.matterport.com/show/?m=AbC123xyz&play=1&qs=1','Matterport model URL allowed');
SELECT throws_ok(format('SELECT public.set_property_tour(%L,''https://evil.example/share/AbC123'')',(SELECT j->>'id' FROM f)),'P0001','Unsupported tour URL','arbitrary host rejected');
SELECT throws_ok(format('SELECT public.set_property_tour(%L,''https://kuula.co.evil.example/share/AbC123'')',(SELECT j->>'id' FROM f)),'P0001','Unsupported tour URL','host suffix bypass rejected');
SELECT throws_ok(format('SELECT public.set_property_tour(%L,''http://kuula.co/share/AbC123'')',(SELECT j->>'id' FROM f)),'P0001','Unsupported tour URL','non-HTTPS rejected');
SELECT throws_ok(format('SELECT public.set_property_tour(%L,''<iframe src="https://kuula.co/share/AbC123"></iframe>'')',(SELECT j->>'id' FROM f)),'P0001','Unsupported tour URL','arbitrary embed HTML rejected');
SELECT throws_ok(format('SELECT public.set_property_tour(%L,''https://my.matterport.com/show/?m=AbC123&redirect=https://evil.example'')',(SELECT j->>'id' FROM f)),'P0001','Unsupported tour URL','arbitrary query parameter rejected');
SELECT is(public.set_property_tour((SELECT (j->>'id')::uuid FROM f),NULL)->'tour_url','null'::jsonb,'owner can clear tour');
SELECT set_config('request.jwt.claims','{"sub":"88888888-0000-4000-8000-000000000002"}',true);
SELECT throws_ok(format('SELECT public.set_property_tour(%L,''https://kuula.co/share/AbC123'')',(SELECT j->>'id' FROM f)),'P0001','Owner required','unrelated user cannot set tour');
SELECT set_config('request.jwt.claims','{"sub":"88888888-0000-4000-8000-000000000003"}',true);
SELECT throws_ok(format('SELECT public.set_property_tour(%L,''https://kuula.co/share/AbC123'')',(SELECT j->>'id' FROM f)),'P0001','Verified email required','unverified writer rejected');
SET LOCAL ROLE anon;
SELECT throws_ok('SELECT public.set_property_tour(gen_random_uuid(),NULL)','42501',NULL,'anonymous tour RPC rejected');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"88888888-0000-4000-8000-000000000001"}',true);
CREATE TEMP TABLE a AS SELECT public.start_auction((SELECT id FROM l),'ascending','public',now()-interval '1 second',now()+interval '1 hour',1000,100) j;
SELECT throws_ok(format('SELECT public.set_property_tour(%L,''https://kuula.co/share/AbC123'')',(SELECT j->>'id' FROM f)),'P0001','Property already has an active auction','active auction prevents material tour change');
SELECT set_config('request.jwt.claims','{"sub":"88888888-0000-4000-8000-000000000002"}',true);
CREATE TEMP TABLE b AS SELECT public.place_bid((SELECT (j->>'id')::uuid FROM a),1000,gen_random_uuid()) j;
UPDATE app.auctions SET ends_at=clock_timestamp()-interval '1 second' WHERE id=(SELECT (j->>'id')::uuid FROM a);
SELECT set_config('request.jwt.claims','{"sub":"88888888-0000-4000-8000-000000000001"}',true);
SELECT public.request_reservation((SELECT (j->>'id')::uuid FROM b),100,gen_random_uuid());
SELECT throws_ok(format('SELECT public.set_property_tour(%L,''https://kuula.co/share/AbC123'')',(SELECT j->>'id' FROM f)),'P0001','Property is reserved','reservation prevents material tour change');
SELECT * FROM finish();
ROLLBACK;
